--
-- Table structure for table `sys_upload_tasks`
--

DROP TABLE IF EXISTS `sys_upload_tasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_upload_tasks` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `file_hash` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件哈希',
  `upload_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MinIO上传ID',
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原始文件名',
  `file_size` bigint DEFAULT NULL COMMENT '文件大小(字节)',
  `content_type` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MIME类型',
  `object_key` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最终存储路径',
  `total_parts` bigint DEFAULT NULL COMMENT '总分片数',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'uploading' COMMENT '状态',
  `user_id` bigint unsigned DEFAULT NULL COMMENT '上传者ID',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `uploaded_parts` bigint DEFAULT '0' COMMENT '已上传分片数',
  `progress` bigint DEFAULT '0' COMMENT '上传进度(0-100)',
  `error_message` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失败原因',
  `completed_at` datetime(3) DEFAULT NULL COMMENT '完成时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_upload_tasks_upload_id` (`upload_id`),
  KEY `idx_sys_upload_tasks_file_hash` (`file_hash`),
  KEY `idx_sys_upload_tasks_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=95 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `sys_upload_tasks`
--

LOCK TABLES `sys_upload_tasks` WRITE;
/*!40000 ALTER TABLE `sys_upload_tasks` DISABLE KEYS */;
