  KEY `idx_sys_uploaded_parts_upload_task_id` (`upload_task_id`)
) ENGINE=InnoDB AUTO_INCREMENT=264 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
